def extract_keywords(text):
    """Extract function-like keywords from text"""
    keywords = []

    # snake_case (2+ parts)
    snake = re.findall(r'\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b', text)
    keywords.extend(snake[:5])

    # PascalCase
    pascal = re.findall(r'\b[A-Z][a-z]+(?:[A-Z][a-z0-9]*)+\b', text)
    keywords.extend(pascal[:3])

    # ALL_CAPS (constants)
    caps = re.findall(r'\b[A-Z][A-Z0-9_]{3,}\b', text)
    keywords.extend(caps[:2])

    return list(dict.fromkeys(keywords))[:10]

def normalize_keyword(kw):
    """Normalize keyword for matching"""
    return re.sub(r'[_\s-]', '', kw.lower())

def match_keywords_to_cache(keywords, cache):
    """Match keywords against cached search results with fuzzy matching"""
    locations = []
    matched_keys = set()

